package org.sleepwell.app;

import android.app.*;import android.content.*;import android.os.Bundle;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;

/** Private draft editor only. Never writes, enables or schedules an alarm. */
public final class SunriseTimeActivity extends Activity {
    static final int REQUEST=786;private Alarm draft;private String request,latitude="",longitude="",error="",preview="";private boolean solar,acknowledged;private int offset;private Dialog picker;private TextView previewView;
    static Intent edit(Activity owner,Alarm alarm,String request){return RecordUi.intent(owner,SunriseTimeActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("request",request);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();draft=Alarm.read(new JSONObject(saved==null?getIntent().getStringExtra("alarm"):saved.getString("draft")));if(draft.nap!=null||draft.napInvalid)throw new IllegalArgumentException();if(saved!=null){latitude=saved.getString("latitude","");longitude=saved.getString("longitude","");solar=saved.getBoolean("solar");acknowledged=saved.getBoolean("acknowledged");offset=saved.getInt("offset");error=saved.getString("error","");preview=saved.getString("preview","");}else if(draft.solar!=null){solar=true;latitude=Double.toString(draft.solar.latitude);longitude=Double.toString(draft.solar.longitude);offset=draft.solar.offset;acknowledged=true;}else if(draft.solarInvalid){solar=true;error="Review the saved sunrise settings, or choose Clock time.";}render();}catch(Exception invalid){finish();}}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Alarm time basis",this::finish);Design.space(body,12);RecordUi.segments(body,new String[]{"Clock time","Sunrise time"},solar?1:0,n->{solar=n==1;preview="";error="";render();});Design.space(body,18);
        if(solar){Design.text(body,"Manual location",18,600,Design.INK);Design.text(body,"Uses this location and your phone’s current time zone. Update coordinates when you travel.",13,400,Design.MUTED);Design.space(body,10);field(body,"Latitude",latitude,value->{latitude=value;clearPreview();});field(body,"Longitude",longitude,value->{longitude=value;clearPreview();});PlanActivity.detail(body,"clock","Sunrise offset",null,offset==0?"At sunrise":(offset>0?"+":"")+offset+" min",()->{int[] values={-120,-90,-60,-45,-30,-15,0,15,30,45,60,90,120};String[] labels=Arrays.stream(values).mapToObj(n->n==0?"At sunrise":(n>0?"+":"")+n+" min").toArray(String[]::new);int selected=-1;for(int n=0;n<values.length;n++)if(values[n]==offset)selected=n;picker=SleepPicker.choices(this,"Sunrise offset",labels,selected,n->{offset=values[n];preview="";render();});});Design.line(body);
            PlanActivity.detail(body,"alarm","Fallback time","Used if sunrise is unavailable on a selected date",Design.clock(this,draft.hour*60+draft.minute),()->picker=SleepPicker.time(this,"Fallback time",draft.hour*60+draft.minute,n->{draft.hour=n/60;draft.minute=n%60;acknowledged=false;preview="";render();}));CheckBox accept=new CheckBox(this);accept.setText("Use "+Design.clock(this,draft.hour*60+draft.minute)+" if sunrise is unavailable");accept.setContentDescription("Confirm sunrise fallback");accept.setTextColor(Design.INK);accept.setTextSize(14*Appearance.scale(this));accept.setTypeface(Design.font(this,400));accept.setMinimumHeight(Design.dp(this,56));accept.setChecked(acknowledged);accept.setOnCheckedChangeListener((v,on)->acknowledged=on);body.addView(accept,new LinearLayout.LayoutParams(-1,-2));Design.space(body,8);Design.button(body,"Calculate next sunrise",false,()->calculate());if(!preview.isEmpty()){previewView=Design.text(body,preview,15,600,Design.BROWN);previewView.setContentDescription("Calculated sunrise preview");}Design.text(body,"Approximate sea-level sunrise, 2000–2100. Terrain, weather and height can shift visible sunrise. Calendar rules may adjust the final alarm.",12,400,Design.MUTED);
        }else Design.text(body,"Uses your selected clock time, date and repeat days.",14,400,Design.MUTED);
        LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView problem=Design.text(footer,error,13,500,NightDialTokens.NEGATIVE);problem.setContentDescription("Sunrise time error");problem.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}Design.button(footer,"Use time basis",true,this::save);
    }
    private void clearPreview(){preview="";if(previewView!=null)previewView.setText("");}
    private void field(LinearLayout body,String title,String value,java.util.function.Consumer<String> changed){Design.text(body,title,13,500,Design.MUTED);EditText input=new EditText(this);input.setSingleLine(true);input.setContentDescription("Sunrise "+title.toLowerCase(Locale.ROOT));input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);input.setText(value);input.setTextColor(Design.INK);input.setTextSize(16*Appearance.scale(this));input.setTypeface(Design.font(this,400));input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(24)});input.setBackground(Design.outline(this,Design.CREAM,Design.LINE,12));Design.pad(input,14,12);body.addView(input,new LinearLayout.LayoutParams(-1,Design.dp(this,52)));input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence text,int start,int count,int after){}public void onTextChanged(CharSequence text,int start,int before,int count){changed.accept(text.toString());}public void afterTextChanged(Editable text){}});Design.space(body,10);}
    private SunriseSchedule configured(boolean requireAcknowledgment){try{return new SunriseSchedule(Double.parseDouble(latitude),Double.parseDouble(longitude),offset,!requireAcknowledgment||acknowledged);}catch(RuntimeException invalid){throw new IllegalArgumentException("Enter latitude −90 to 90, longitude −180 to 180, and confirm your fallback time.");}}
    private void calculate(){try{SunriseSchedule value=configured(false);long now=AlarmSkips.clock.getAsLong();ZoneId zone=ZoneId.systemDefault();long at=value.next(draft.hour,draft.minute,draft.days,draft.date,now,zone,null);if(at<=0)throw new IllegalArgumentException("Choose a future alarm date in Edit alarm.");LocalDate date=Instant.ofEpochMilli(at).atZone(zone).toLocalDate();SunriseSchedule.Result result=value.on(date,draft.hour,draft.minute,zone);preview=date+" · "+RecordUi.clock(this,at,zone)+"\n"+result.reason;error="";}catch(IllegalArgumentException invalid){error=invalid.getMessage();preview="";}render();}
    private void save(){try{SunriseSchedule value=solar?configured(true):null;Intent result=new Intent().putExtra("request",request).putExtra("clock",!solar).putExtra("hour",draft.hour).putExtra("minute",draft.minute);if(value!=null)result.putExtra("solar",SunriseScheduleJson.encode(value).toString());setResult(RESULT_OK,result);finish();}catch(IllegalArgumentException invalid){error=invalid.getMessage();render();}}
    @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putString("draft",draft.json().toString());saved.putString("latitude",latitude);saved.putString("longitude",longitude);saved.putBoolean("solar",solar);saved.putBoolean("acknowledged",acknowledged);saved.putInt("offset",offset);saved.putString("error",error);saved.putString("preview",preview);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    @Override protected void onDestroy(){if(picker!=null)picker.dismiss();super.onDestroy();}
}
